-- Clinic Care: fresh database schema. Never import over an existing unrelated database.
SET NAMES utf8mb4;
CREATE TABLE settings (`key` VARCHAR(80) PRIMARY KEY, `value` TEXT NOT NULL) ENGINE=InnoDB;
INSERT INTO settings VALUES ('clinic_name','Clinic Care'),('clinic_address','উল্লাপাড়া, সিরাজগঞ্জ'),('clinic_phone',''),('currency','BDT');
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, remember_token VARCHAR(100) NULL, role ENUM('admin','reception','doctor','nurse','lab','cashier') NOT NULL, active TINYINT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL, ip VARCHAR(64) NOT NULL, occurred_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(email,occurred_at), INDEX(ip,occurred_at)) ENGINE=InnoDB;
CREATE TABLE patients (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, birth_date DATE NULL, age_years SMALLINT UNSIGNED NULL, gender ENUM('female','male','other') NOT NULL, phone VARCHAR(30) NOT NULL, address TEXT NULL, emergency_contact VARCHAR(150) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(phone), INDEX(name)) ENGINE=InnoDB;
CREATE TABLE doctors (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, specialty VARCHAR(150) NOT NULL, phone VARCHAR(30) NULL, fee DECIMAL(12,2) NOT NULL DEFAULT 0, followup_fee DECIMAL(12,2) NOT NULL DEFAULT 0, available_days VARCHAR(150) NULL, start_time TIME NULL, end_time TIME NULL, active TINYINT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE beds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, ward VARCHAR(100) NOT NULL, type ENUM('ward','cabin','icu') NOT NULL DEFAULT 'ward', daily_rate DECIMAL(12,2) NOT NULL, state ENUM('available','cleaning','inactive') NOT NULL DEFAULT 'available', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE visits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, patient_id BIGINT UNSIGNED NOT NULL, doctor_id BIGINT UNSIGNED NOT NULL, appointment_at DATETIME NOT NULL, serial_no INT UNSIGNED NOT NULL, visit_type ENUM('new','followup') NOT NULL DEFAULT 'new', fee DECIMAL(12,2) NOT NULL, status ENUM('waiting','completed','cancelled') NOT NULL DEFAULT 'waiting', notes TEXT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(patient_id) REFERENCES patients(id), FOREIGN KEY(doctor_id) REFERENCES doctors(id), UNIQUE KEY doctor_serial(doctor_id,appointment_at,serial_no), INDEX(appointment_at)) ENGINE=InnoDB;
CREATE TABLE admissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, patient_id BIGINT UNSIGNED NOT NULL, doctor_id BIGINT UNSIGNED NOT NULL, admitted_at DATETIME NOT NULL, reason TEXT NOT NULL, status ENUM('admitted','discharged','cancelled') NOT NULL DEFAULT 'admitted', discharged_at DATETIME NULL, treatment_summary TEXT NULL, followup_notes TEXT NULL, discharge_type ENUM('regular','transfer','own_risk') NOT NULL DEFAULT 'regular', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(patient_id) REFERENCES patients(id), FOREIGN KEY(doctor_id) REFERENCES doctors(id), INDEX(status)) ENGINE=InnoDB;
CREATE TABLE bed_stays (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, admission_id BIGINT UNSIGNED NOT NULL, bed_id BIGINT UNSIGNED NOT NULL, started_at DATETIME NOT NULL, ended_at DATETIME NULL, daily_rate DECIMAL(12,2) NOT NULL, FOREIGN KEY(admission_id) REFERENCES admissions(id), FOREIGN KEY(bed_id) REFERENCES beds(id), INDEX(bed_id,ended_at)) ENGINE=InnoDB;
CREATE TABLE nursing_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, admission_id BIGINT UNSIGNED NOT NULL, recorded_at DATETIME NOT NULL, blood_pressure VARCHAR(30) NULL, temperature DECIMAL(5,2) NULL, pulse SMALLINT UNSIGNED NULL, notes TEXT NULL, user_id BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(admission_id) REFERENCES admissions(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE tests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL UNIQUE, sample_type VARCHAR(80) NOT NULL, price DECIMAL(12,2) NOT NULL, turnaround_hours SMALLINT UNSIGNED NOT NULL DEFAULT 24, active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE test_parameters (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, test_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, unit VARCHAR(60) NULL, reference_range VARCHAR(150) NULL, sort_order INT NOT NULL DEFAULT 0, FOREIGN KEY(test_id) REFERENCES tests(id), UNIQUE(test_id,name)) ENGINE=InnoDB;
CREATE TABLE invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, patient_id BIGINT UNSIGNED NOT NULL, visit_id BIGINT UNSIGNED NULL UNIQUE, admission_id BIGINT UNSIGNED NULL UNIQUE, discount DECIMAL(12,2) NOT NULL DEFAULT 0, status ENUM('open','finalized','void') NOT NULL DEFAULT 'open', notes TEXT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(patient_id) REFERENCES patients(id), FOREIGN KEY(visit_id) REFERENCES visits(id), FOREIGN KEY(admission_id) REFERENCES admissions(id)) ENGINE=InnoDB;
CREATE TABLE lab_orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, patient_id BIGINT UNSIGNED NOT NULL, admission_id BIGINT UNSIGNED NULL, invoice_id BIGINT UNSIGNED NOT NULL, test_id BIGINT UNSIGNED NOT NULL, status ENUM('ordered','collected','processing','review','approved','cancelled') NOT NULL DEFAULT 'ordered', ordered_at DATETIME NOT NULL, collected_at DATETIME NULL, approved_at DATETIME NULL, approved_by BIGINT UNSIGNED NULL, report_notes TEXT NULL, FOREIGN KEY(patient_id) REFERENCES patients(id), FOREIGN KEY(admission_id) REFERENCES admissions(id), FOREIGN KEY(invoice_id) REFERENCES invoices(id), FOREIGN KEY(test_id) REFERENCES tests(id), FOREIGN KEY(approved_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE lab_results (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, parameter_name VARCHAR(150) NOT NULL, result_value VARCHAR(150) NOT NULL, unit VARCHAR(60) NULL, reference_range VARCHAR(150) NULL, FOREIGN KEY(order_id) REFERENCES lab_orders(id), UNIQUE(order_id,parameter_name)) ENGINE=InnoDB;
CREATE TABLE invoice_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invoice_id BIGINT UNSIGNED NOT NULL, description VARCHAR(255) NOT NULL, quantity DECIMAL(10,2) NOT NULL DEFAULT 1, unit_price DECIMAL(12,2) NOT NULL, kind ENUM('visit','bed','test','service') NOT NULL DEFAULT 'service', bed_stay_id BIGINT UNSIGNED NULL UNIQUE, lab_order_id BIGINT UNSIGNED NULL UNIQUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(invoice_id) REFERENCES invoices(id), FOREIGN KEY(bed_stay_id) REFERENCES bed_stays(id), FOREIGN KEY(lab_order_id) REFERENCES lab_orders(id)) ENGINE=InnoDB;
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invoice_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL, type ENUM('receipt','refund') NOT NULL DEFAULT 'receipt', method ENUM('cash','bkash','nagad','bank') NOT NULL, transaction_ref VARCHAR(150) NULL, reason VARCHAR(255) NULL, paid_at DATETIME NOT NULL, user_id BIGINT UNSIGNED NOT NULL, voided_at DATETIME NULL, void_reason VARCHAR(255) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(invoice_id) REFERENCES invoices(id), FOREIGN KEY(user_id) REFERENCES users(id), INDEX(paid_at)) ENGINE=InnoDB;
CREATE TABLE expenses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category VARCHAR(100) NOT NULL, description VARCHAR(255) NOT NULL, amount DECIMAL(12,2) NOT NULL, method ENUM('cash','bkash','nagad','bank') NOT NULL, expense_date DATE NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE doctor_ledgers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, doctor_id BIGINT UNSIGNED NOT NULL, type ENUM('payable','settlement') NOT NULL, amount DECIMAL(12,2) NOT NULL, entry_date DATE NOT NULL, notes VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(doctor_id) REFERENCES doctors(id)) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, action VARCHAR(80) NOT NULL, entity VARCHAR(80) NOT NULL, entity_id BIGINT UNSIGNED NULL, details TEXT NULL, ip VARCHAR(64) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
